SELECT 
FROM analysis_jobs
WHERE case_id = #{caseId}
  AND search_condition_id = #{searchConditionId}
  AND recording_id = #{recordingId}
  AND job_type = 'RECORDING_ANALYSIS'
  AND status IN ('QUEUED', 'RUNNING')
ORDER BY id DESC
LIMIT 1

SELECT 
FROM analysis_jobs
WHERE case_id = #{caseId}
  AND id = #{jobId}
  AND job_type = 'RECORDING_ANALYSIS'

SELECT FROM analysis_jobs WHERE job_type = 'RECORDING_ANALYSIS' AND case_id IN
#{caseId}
ORDER BY requested_at DESC, id DESC

